import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Validate that a quantity is a positive integer.
 * @param {*} qty
 * @returns {boolean}
 */
function isValidQty(qty) {
  return Number.isInteger(qty) && qty > 0;
}

/**
 * Validate that a discount percent is a number between 0 and 100.
 * @param {*} discountPercent
 * @returns {boolean}
 */
function isValidDiscountPercent(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Validate that terms are valid.
 * @param {*} terms
 * @returns {boolean}
 */
function isValidTerms(terms) {
  return ['NET14', 'NET30', 'EOM'].includes(terms);
}

/**
 * Calculate the due date based on terms and issue date.
 * @param {string} issueDate YYYY-MM-DD format
 * @param {string} terms NET14, NET30, or EOM
 * @returns {string} due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    const [yearStr, monthStr] = issueDate.split('-');
    const year = parseInt(yearStr);
    const month = parseInt(monthStr);
    const date = new Date(Date.UTC(year, month - 1, 1));
    date.setUTCMonth(date.getUTCMonth() + 1);
    date.setUTCDate(0);
    const y = date.getUTCFullYear();
    const m = (date.getUTCMonth() + 1).toString().padStart(2, '0');
    const d = date.getUTCDate().toString().padStart(2, '0');
    return `${y}-${m}-${d}`;
  }
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  if (!isValidTerms(terms)) return fail('TERMS_INVALID');

  // Calculate due date
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Build lines with product details
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!isValidQty(line.qty)) return fail('QTY_INVALID');

    // Determine discount: explicit wins, otherwise use customer tier
    let discountPercent;
    if ('discountPercent' in line) {
      discountPercent = line.discountPercent;
    } else {
      discountPercent = TIER_DISCOUNTS[customer.tier] ?? 0;
    }
    if (!isValidDiscountPercent(discountPercent)) return fail('DISCOUNT_INVALID');

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms,
    dueDate,
    lines: invoiceLines,
  });
}

/**
 * Calculate the total amount for a single line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  const discount = total * (discountPercent / 100);
  return Math.max(0, Math.round(discount));
}

/**
 * Calculate VAT for a single line (on amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const afterDiscount = Math.max(0, total - discount);
  const vatRate = line.vatRate ?? 0;
  const vat = afterDiscount * (vatRate / 100);
  return Math.max(0, roundCents(vat));
}

/**
 * Calculate invoice totals (subtotal, discount, vat, and total).
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const total = Math.max(0, subtotal - discount + vat);
  return { subtotal, discount, vat, total };
}

/**
 * Add a line to an invoice or increase qty if SKU already exists.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} param
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, lineParam) {
  const { sku, qty, discountPercent } = lineParam;

  // Check draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!isValidQty(qty)) return fail('QTY_INVALID');

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Determine discount: explicit wins, otherwise use customer tier
  let finalDiscount;
  if ('discountPercent' in lineParam) {
    finalDiscount = discountPercent;
  } else {
    finalDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
  }
  if (!isValidDiscountPercent(finalDiscount)) return fail('DISCOUNT_INVALID');

  // Get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Check if SKU already exists on invoice
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  // Create new lines array
  const newLines = invoice.lines.map((line) => ({ ...line }));

  if (existingLineIndex >= 0) {
    // Increase qty on existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscount,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line to remove
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check that we're not removing the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without the removed line
  const newLines = invoice.lines.filter((line, i) => i !== lineIndex);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue an invoice (assign a number and change status to 'issued').
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Generate next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

